        QString args="-NoProfile -ExecutionPolicy Bypass -File \""+root+"/_internal/gui-action.ps1\" -Root \""+root+"\" -Action "+verb+" -Component "+component+" -TcpPort "+QString::number(tcp->value())+" -UdpPort "+QString::number(udp->value())+" -TimeoutMs "+QString::number(timeout->value());
