        QString health="等待连接";if(up){health="已连接 · 等待媒体数据";if(hasMedia)health=state.value("rtt_ms").toDouble()>100||media.value("network_frame_drop_percent").toDouble()>2||media.value("queue_ms").toDouble()>30?"连接需关注":"采样指标正常";}quality->setText(health);quality->setToolTip("经验提示：隧道 RTT > 100 ms、媒体网络丢帧 > 2% 或帧排队 > 30 ms；并非完整体验评分。");
        devices->setRowCount(up?1:0);sessionCount->setText(fresh?QString::number(up?1:0)+" 个已认证隧道会话":"会话数量未知");
        if(up){QString name=peer.value("device_name").toString("已认证客户端 · 旧版未上报设备名").left(128);QString mode=peer.value("transport").toString(state.value("transport").toString());mode=mode=="udp"?"UDP":mode=="tcp_fallback"?"TCP 兼容通道":"探测中";auto seconds=qint64(state.value("connected_seconds").toDouble());QString duration=QString("%1:%2:%3").arg(seconds/3600,2,10,QChar('0')).arg(seconds/60%60,2,10,QChar('0')).arg(seconds%60,2,10,QChar('0'));QStringList values{name,mode,duration,hasMedia?"媒体数据更新中":"已认证"};for(int i=0;i<4;i++)devices->setItem(0,i,new QTableWidgetItem(values[i]));
            deviceDetail->setText(QString("活动 TCP %1 · UDP 流 %2 · 发送队列 %3 KB · 本地丢弃 %4 · 重连 %5\n%6").arg(state.value("active_tcp_streams").toInt()).arg(state.value("active_udp_flows").toInt()).arg(state.value("queued_bytes").toDouble()/1024,0,'f',1).arg(state.value("udp_local_dropped").toDouble(),0,'f',0).arg(state.value("reconnects").toDouble(),0,'f',0).arg(hasMedia?"媒体指标由主控端回传；网络丢帧包含最终无法恢复的视频帧，不等同于 UDP 丢包。":"需新版主控端且开始串流，才有帧率、丢帧和解码数据。"));
        }else deviceDetail->setText("mslink 当前支持单个已认证隧道客户端；配对设备列表与正在连接的设备是不同概念。");
        lastUpdate->setToolTip(identityLimited?"当前权限无法核验后台进程路径，已核对 PID 与进程名；采样来自所选安装目录。":"进程路径与采样时间已校验。");lastUpdate->setText(fresh?"● 实时数据 · "+QDateTime::fromMSecsSinceEpoch(qint64(stamp)).toString("HH:mm:ss"):"○ 等待遥测");
